import csv
import hashlib
import json
from pathlib import Path
import re

OUT = Path(__file__).resolve().parent
B01 = OUT.parent.parent.parent / "blind-01" / "m5"
records = json.loads((OUT / "records.json").read_text())
checks = json.loads((OUT / "reachability.json").read_text())["checks"]
files = {f["input"]: f for f in records["files"]}
reach = {c["input"]: c for c in checks}
assert set(files) == set(reach)
all_reachable = all(c["reachable"] for c in checks)

DECISIONS = [
    ('Owner’s answer, 2026-11-02, case identities', '"Codex addendum": a Codex reader copies the four case identities, their prepared input records and reference-structure sources from blind-01\'s records into a labelled section added to the brief. Your text stays unchanged.'),
    ('Owner’s answer, 2026-11-02, same data location', '"Yes, same mirror": the addendum also lists the mirror\'s URLs and SHA-256 hashes from blind-01\'s records, with provenance kept as unverified_mirror.'),
    ('Owner’s words, 2026-10-31, first paragraph', 'I approve option 2: proceed with the unverified mirror for this local experiment. This supersedes the acquisition instruction that an unverified mirror can never count as usable. I think generally speaking, this rule is too hard - the mirror becomes usable from our use and results.'),
    ('Owner’s words, 2026-10-31, third paragraph', 'Keep all scientific checks unchanged. Passing published-value anchors checks the properties those anchors measure; it does not prove the copy matches the original. Preserve that uncertainty in any resulting claims.'),
]

def remote_row(key, role):
    f = files[key]
    return f"| {role}: `{key}` | {f['url']} | {f['bytes']} | `{f['sha256']}` |"

parts = ["## Materials from blind-01 records (owner decisions 2026-11-02; recorded by an authorized reader agent)\n"]
for title, quote in DECISIONS:
    parts.append(f"{title}:\n\n> {quote}\n")
parts.append("The FroDock distribution in these records has provenance `unverified_mirror`. The four recorded units are apo pairings from PINDER release `2024-02`, sampled at zero-based unit-manifest indices `3, 5, 9, 15`. Their recorded examination was a FroDock CPU/MPI unit-concurrency probe whose listed comparison outputs were fifty final ranked PDBs per unit. The identities and input records below are those sampled units.\n")
parts.append("### Cases and prepared input records\n\nEach fenced CSV block is the original UTF-8 header followed by one original selected record, with LF line endings and a final LF. The path strings in those records are logical prepared-input names emitted by the recorded preprocessing; remote source locations are given separately. The full four-unit selection, in the order below, is 644 bytes with SHA-256 `f34c87e11bc77f02997f41aaae17cf6958ce02976b9621886d96c03029b27af0`.\n")
for n, c in enumerate(records["cases"], 1):
    entry = c["index_record"]
    parts.append(f"#### {n}. `{c['id']}`\n\nPINDER system: `{c['system_id']}`; kind: `apo`; unit index: `{c['manifest_index']}`. In the recorded index entry, `pinder_s=True`, `apo_R=True`, `apo_L=True`; `apo_R_pdb={entry['apo_R_pdb']}` and `apo_L_pdb={entry['apo_L_pdb']}`.\n")
    parts.append(f"Prepared CSV block: {c['csv_bytes']} bytes; SHA-256 `{c['csv_sha256']}`. The record alone, excluding header, is {c['record_line_bytes']} bytes with SHA-256 `{c['record_line_sha256']}`.\n\n```csv\nid,kind,receptor,ligand\n{c['prepared_record']}```\n")
    parts.append("The source-index selection is the single row whose `id` equals the system identifier above, with pairing `apo` and its recorded canonical `apo_R_pdb` / `apo_L_pdb` fields. The recorded preprocessing reads those complete monomer files, assigns chain labels `R` and `L` to receptor and ligand respectively, and serializes them to the named prepared PDBs. This describes the recorded input origin; no new residue or atom selection is introduced.\n")
    parts.append("| Input source or reference location | Fetch URL | Recorded bytes | Recorded SHA-256 |\n| --- | --- | ---: | --- |")
    parts.append(remote_row("index.parquet", "Index source; exact row selection above"))
    for role, key in zip(("Canonical receptor source", "Canonical ligand source"), c["primary"]):
        parts.append(remote_row(key, role))
    parts.append(remote_row(c["native"], "Reference native bound complex"))
    parts.append("\nThe reference location is a directly fetched PDB, so no archive-member path applies. Reference contents are not included here.\n")

parts.append("### Recorded data and source locations\n\nThis inventory contains the four entries’ recorded structural/mapping locations, index and metadata, the test-monomer archive, PINDER source and the FroDock distribution with provenance `unverified_mirror`. Auxiliary predicted/alternative-apo files are included because the recorded PINDER entry downloader enumerates them; they are not additional selected cases or prepared apo records. The native reference files above are separate from the test-monomer ZIP.\n")
zipfile = files["test_set_pdbs.zip"]
parts.append(f"The recorded test-monomer archive is {zipfile['url']} ({zipfile['bytes']} bytes; SHA-256 `{zipfile['sha256']}`). Its separated holo members associated with these identities are:\n")
for c in records["cases"]:
    parts.append(f"- `{c['holo'][0]}` and `{c['holo'][1]}`.")
parts.append("\nThe canonical apo files and native reference complexes listed above are not members of that ZIP. Their direct URLs are recorded individually.\n")
parts.append("Reachability checks used anonymous HTTPS HEAD requests from this reader’s machine, with no login and no payload download. Times below are UTC check completion times. Byte counts and SHA-256 values are copied from blind-01’s recorded inventory; these HEAD checks establish current reachability, not a new payload-hash comparison.\n")
parts.append("| Input | Exact fetch URL | Provenance | HEAD completed UTC | Recorded bytes | Recorded SHA-256 |\n| --- | --- | --- | --- | ---: | --- |")
for f in records["files"]:
    c = reach[f["input"]]
    parts.append(f"| `{f['input']}` | {f['url']} | `{f['provenance']}` | {c['completed_utc']} | {f['bytes']} | `{f['sha256']}` |")

parts.append("\n### Software pins from blind-01 run9’s records\n\nThese are historical run9 records. They do not specify blind-02 configurations.\n")
parts.append("- **MEGADOCK:** the inspected run9 intake, harness and saved setup records contain no MEGADOCK repository/package, commit, tag/release, build command, CPU/GPU implementation pin, build-option pin, or standard/denser rotational-sampling option. No MEGADOCK setting has been added to this materials record.\n- **PINDER, including run9’s DockQ implementation:** repository identifier `https://github.com/pinder-org/pinder`, commit `ebeb28a2f8411363cef722b7d293c978f7442672`, tree `adc153de2eef1ac428c1136d609b30728c88cc7b`. The fetchable source archive, size and SHA-256 are in the inventory above; archive root is `pinder-ebeb28a2f8411363cef722b7d293c978f7442672/`. No tag/release was recorded. Installed version was the archive-build SCM value `0.0.0+gebeb28a2`. Run9 used the `pinder_eval` DockQ implementation in this repository; a separate standalone DockQ package/release pin was not recorded.\n- **Run9’s actual docking software, FroDock:** distribution provenance `unverified_mirror`, README label `FRODOCK 3.12`, dated February 8, 2020. No FroDock git commit or authenticated original release hash was established. Archive root is `frodock3_linux64/`; its URL, bytes and SHA-256 appear above. The four run9 GNU/MPI tools were recorded as compiled: `frodockgrid_mpi_gcc`, `frodock_mpi_gcc`, `frodockcluster_gcc`, `frodockview_gcc`. The archive’s `frodock3_linux64/bin/soap.bin` was recorded as 7,536,604 bytes, SHA-256 `791f31ec8ef1ef1466092b425638e926755519c9626f5678ca675ef6c76234fc`; it is an internal member, not another fetch location.\n")
parts.append("Run9’s recorded build/install commands included the following exact script excerpts. Variable names denote that run’s logical build layout.\n\n```sh\npython3 -m venv --system-site-packages \"$VENV\"\n\"$VPY\" -m pip install --no-cache-dir --upgrade \"setuptools>=64\" \"setuptools_scm>=8\" packaging wheel 2>&1 \\\n  | tee \"$SOUT/pip_install_build_tools.log\"\nSETUPTOOLS_SCM_PRETEND_VERSION=\"$PINDER_SCM_VERSION\" SETUPTOOLS_SCM_PRETEND_VERSION_FOR_PINDER=\"$PINDER_SCM_VERSION\" \\\n  \"$VPY\" -m pip install --no-cache-dir --no-build-isolation \"$WORK/$BP/pinder-src\" 2>&1 | tee \"$SOUT/pip_install_pinder.log\"\n\"$VPY\" -m pip install --no-cache-dir fire 2>&1 | tee \"$SOUT/pip_install_fire.log\"\nprintf 'numpy<2\\n' > \"$SOUT/venv_constraints.txt\"\n\"$VPY\" -m pip install --no-cache-dir --upgrade -c \"$SOUT/venv_constraints.txt\" networkx pandas scikit-learn 2>&1 \\\n  | tee \"$SOUT/pip_install_venv_refresh.log\"\n```\n")
parts.append("Run9’s FroDock build invocation was `( cd \"$BP/frodock\" && ./compile_frodock.sh )`. Run9 also applied a recorded PINDER adapter/entry-point repair patch, SHA-256 `295af03d22550b21c1e0852f723f324c35e9f5caa75e1759ba82bee5ed0259c3`, before installation. The patch repaired CSV reading, entry-point dispatch, input staging, binary-path construction, output copying and relative input-path resolution. The measured wrapper additionally contained ligand HETATM chain-label restoration. These are part of the recorded run9 baseline, not a pristine-source assertion.\n")
parts.append("Run9’s saved environment record gives Python `3.10.12`, Open MPI `4.1.2`, stock and venv torch `2.7.0`, Intel Xeon Platinum `8480+`, and 26 host logical CPUs. Its CUDA layout was `distro`, with `nvcc=/usr/bin/nvcc`, includes `/usr/include`, and libraries `/usr/lib/x86_64-linux-gnu`; the recorded FroDock build did not use CUDA. The run9 docking wrapper exposed zero GPUs (`CUDA_VISIBLE_DEVICES=\"\"`), used eight MPI ranks and fifty solutions, and scored through PINDER. The saved freeze includes `biotite==1.2.0`, `numpy==1.26.4`, `networkx==3.4.2`, `pandas==2.3.3`, `scikit-learn==1.7.2`, `pyarrow==25.0.1`, `fire==0.7.1`, `packaging==26.3`, and `setuptools-scm==10.3.4`. The setup record reports no apt packages newly installed; the setup script listed GNU/build tools, Open MPI, FFTW and HDF5 packages. No immutable base-image digest or complete OS dependency lock was recorded.\n")
parts.append("The FroDock distribution with provenance `unverified_mirror` contained compiled/prebuilt alternatives; run9 recorded all four required tools as compiled. Its README and build-script version labels differ internally, as recorded in blind-01. Those records supply no MEGADOCK implementation or sampling-option evidence.\n")
parts.append("The mirror copy’s identity with the original is unverified. Agreement with published-value anchors checks only the properties those anchors measure and does not establish that identity.\n")
def markdown(blocks):
    # Keep table rows contiguous when assembling paragraph-sized fragments.
    return re.sub(r"(?m)(^\|[^\n]*\n)\n+(?=\|)", r"\1", "\n\n".join(blocks))

addendum = markdown(parts).encode()
seed = (OUT.parent / "BRIEF.md").read_bytes()
if all_reachable and len(records["cases"]) == 4:
    (OUT / "BRIEF_run1.md").write_bytes(seed + b"\n" + addendum)

with (OUT / "HASHES.tsv").open("w", newline="") as f:
    writer = csv.DictWriter(f, fieldnames=["input", "url", "bytes", "sha256", "source_record", "reachable"], delimiter="\t", lineterminator="\n")
    writer.writeheader()
    for item in records["files"]:
        writer.writerow({k: item[k] if k != "reachable" else str(reach[item["input"]]["reachable"]).lower() for k in writer.fieldnames})

